export function WeatherSymbols(){return <svg aria-hidden="true" width="0" height="0" style={{position:'absolute',overflow:'hidden',pointerEvents:'none'}}><defs dangerouslySetInnerHTML={{__html:symbols}}/></svg>;}
export function WeatherGlyph({code,daylight=true,x=0,y=0,size=24,nightTrack=false}:{code:string;daylight?:boolean;x?:number;y?:number;size?:number;nightTrack?:boolean}){return <use style={nightTrack&&!preservesConditionColorAtNight(code)?{'--sun':'var(--night)','--rain':'var(--night)','--wind':'var(--night)','--cloud':'var(--night)','--hot':'var(--night)','--secondary':'var(--night)'} as CSSProperties:undefined} href={`#weather-${conditionIcon(code,daylight)}`} x={x} y={y} width={size} height={size}/>;}
export function WeatherIcon({code,daylight=true,size=28}:{code:string;daylight?:boolean;size?:number}){return <svg className="weather-icon" width={size} height={size} viewBox="0 0 24 24" aria-hidden="true"><WeatherGlyph code={code} daylight={daylight}/></svg>;}
